        right = s[length // 2 + 1:]
    else:
        left = s[:length // 2]
        middle = ''
        right = s[length // 2:]

    # Construct palindrome by mirroring left + middle
    palindrome = make_palindrome(left, middle, odd_len)

    if palindrome > num:
        return palindrome

    # Need to increment the middle part and then mirror again
    if odd_len:
        # Increment middle digit(s)
        middle_num = int(middle)
        left_num = int(left) if left else 0
        # Try incrementing middle digit
        if middle_num < 9:
            middle_num += 1
            return make_palindrome(left, str(middle_num), True)
        else:
            # middle digit is 9, set to 0 and increment left part
            middle_num = 0
            left_num += 1
            left_str = str(left_num).zfill(len(left))
            # If length increased (e.g. 99 + 1 = 100)
            if len(left_str) > len(left):
                # This means palindrome length increases by 1
                # Construct palindrome of new length
                return int('1' + ('0' * (length - 1)) + '1')
            else:
                return make_palindrome(left_str, str(middle_num), True)
    else:
        # Even length: increment left part and mirror
        left_num = int(left)
        left_num += 1
        left_str = str(left_num).zfill(len(left))
        if len(left_str) > len(left):
            # length increases by 1, e.g. 9999 -> 10001
            return int('1' + ('0' * (length -1)) + '1')
        else:
            return make_palindrome(left_str, '', False)

