def get_total_number_of_sequences(n: int, max_value: int) -> int:
    # dp[i][x] = number of sequences of length i ending with value x
    # Transitions: for each x in 1..max_value,
    # sum dp[i-1][y] for y where x >= 2*y

    if n == 1:
        return max_value

    dp_prev = [1] * (max_value + 1)  # sequences of length 1 ending at x (1 for each x)

    for length in range(2, n + 1):
        dp_curr = [0] * (max_value + 1)
        # prefix sums of dp_prev to quickly sum over y where y <= x//2
        prefix = [0] * (max_value + 2)
        for i in range(1, max_value + 1):
            prefix[i] = prefix[i - 1] + dp_prev[i]

        for x in range(1, max_value + 1):
            limit = x // 2
            if limit >= 1:
                dp_curr[x] = prefix[limit]
            else:
                dp_curr[x] = 0
        dp_prev = dp_curr

    return sum(dp_prev[1:])

