def next_smallest_palindrome(n: int) -> int:
    s = str(n + 1)
    length = len(s)

    def is_palindrome(x: str) -> bool:
        return x == x[::-1]

    # If all 9's, e.g., 9, 99, 999 -> next palindrome is 10..01 with length+1
    if all(ch == '9' for ch in s):
        return int('1' + ('0' * (length - 1)) + '1')

    while True:
        if is_palindrome(s):
            return int(s)
        # Generate the next palindrome candidate by mirroring left half to right
        half = (length + 1) // 2
        left = s[:half]
        if length % 2 == 0:
            pal_candidate = left + left[::-1]
        else:
            pal_candidate = left + left[-2::-1]

        if int(pal_candidate) >= int(s):
            s = pal_candidate
        else:
            # Increment the left half and mirror again
            left_num = int(left) + 1
            left = str(left_num)
            if len(left) > half:  # e.g. 999 + 1 = 1000 increases length
                length += 1
                s = '1' + ('0' * (length - 1))
