def find_solution(a, b, n):
    # We want non-negative integers x,y satisfying a*x + b*y = n

    # Handle special cases:
    if a == 0 and b == 0:
        return (0, 0) if n == 0 else None
    if a == 0:
        if n % b == 0 and n // b >= 0:
            return (0, n // b)
        else:
            return None
    if b == 0:
        if n % a == 0 and n // a >= 0:
            return (n // a, 0)
        else:
            return None

    from math import gcd

    g = gcd(a, b)
    if n % g != 0:
        return None

    # Extended Euclidean algorithm to find one solution to a*x + b*y = g
    def extended_gcd(aa, bb):
        if bb == 0:
            return (aa, 1, 0)
        g, x1, y1 = extended_gcd(bb, aa % bb)
        x = y1
        y = x1 - (aa // bb) * y1
        return (g, x, y)

    g, x0, y0 = extended_gcd(a, b)
    # Scale the solution to a*x + b*y = n
    x0 *= n // g
    y0 *= n // g

    # General solution: x = x0 + k*(b/g), y = y0 - k*(a/g)
    # We want to find k such that x >= 0 and y >= 0

    # Let:
    #   A = b//g
    #   B = a//g
    A = b // g
    B = a // g

    # x >= 0 => x0 + k*A >= 0 => k >= -x0/A
    # y >= 0 => y0 - k*B >= 0 => k <= y0/B

    # Compute bounds for k (ceil and floor carefully)
    from math import ceil, floor

    k_min = ceil(-x0 / A) if A != 0 else float('-inf')
    k_max = floor(y0 / B) if B != 0 else float('inf')

    if k_min > k_max:
        return None

    # Any k in [k_min, k_max] yields a solution.
    # Return one such solution, e.g., k = k_min
    k = k_min
    x = x0 + k * A
    y = y0 - k * B

    if x < 0 or y < 0:
        # Just in case of rounding errors
        return None

    return (x, y)

