def dict_depth(d):
    if not isinstance(d, dict):
        return 0
    max_depth = 0
    for v in d.values():
        if isinstance(v, dict):
            depth = dict_depth(v)
            if depth > max_depth:
                max_depth = depth
        elif isinstance(v, (list, tuple)):
            # Check if any element in list/tuple is dict or list/tuple,
            # but per clarification, only dictionaries add depth,
            # and lists/tuples themselves do not add depth.
            # So just scan elements for dicts to get max depth among them.
            for item in v:
                if isinstance(item, dict):
                    depth = dict_depth(item)
                    if depth > max_depth:
                        max_depth = depth
                elif isinstance(item, (list, tuple)):
                    # Recursively check nested lists/tuples for dicts
                    # but they themselves do not add depth.
                    # So we scan inside.
                    def get_max_depth_in_seq(seq):
                        local_max = 0
                        for elem in seq:
                            if isinstance(elem, dict):
                                ddepth = dict_depth(elem)
                                if ddepth > local_max:
                                    local_max = ddepth
                            elif isinstance(elem, (list, tuple)):
                                subdepth = get_max_depth_in_seq(elem)
                                if subdepth > local_max:
                                    local_max = subdepth
                        return local_max
                    depth = get_max_depth_in_seq(item)
                    if depth > max_depth:
                        max_depth = depth
    return 1 + max_depth

