def next_smallest_palindrome(num: int) -> int:
    s = str(num)
    length = len(s)

    # If all digits are 9, the next palindrome is 10..01 with length+1 digits
    if all(ch == '9' for ch in s):
        return int('1' + ('0' * (length - 1)) + '1')

    def is_palindrome(x: str) -> bool:
        return x == x[::-1]

    def mirror_left_to_right(x: str) -> str:
        half = length // 2
        if length % 2 == 0:
            return x[:half] + x[:half][::-1]
        else:
            return x[:half + 1] + x[:half][::-1]

    # Start with palindrome formed by mirroring left half to right
    palindrome = mirror_left_to_right(s)

    # If palindrome is greater than num, return it
    if int(palindrome) > num:
        return int(palindrome)

    # Otherwise, increment the middle part and mirror again
    # Convert to list for easier manipulation
    arr = list(s)
    mid = length // 2

    # Determine the left half + middle to increment
    if length % 2 == 0:
        left_part = arr[:mid]
        # increment left part as a number and handle carry
        left_num = int(''.join(left_part)) + 1
        left_str = str(left_num).rjust(mid, '0')
        # mirror left_str to right
        palindrome = left_str + left_str[::-1]
    else:
        left_part = arr[:mid + 1]
        left_num = int(''.join(left_part)) + 1
        left_str = str(left_num).rjust(mid + 1, '0')
        palindrome = left_str + left_str[:-1][::-1]

    return int(palindrome)

