def get_total_number_of_sequences(n: int, m: int) -> int:
    # dp[i][x] = number of sequences of length i ending with x
    # i ranges from 1 to n
    # x ranges from 1 to m

    if n == 1:
        return m  # any first element from 1 to m

    dp_prev = [1] * (m + 1)  # for i=1, all sequences of length 1 ending with x=1..m are 1
    # prefix sums for dp_prev to optimize counting
    for length in range(2, n + 1):
        dp_curr = [0] * (m + 1)
        # prefix sum of dp_prev to quickly sum ranges
        prefix = [0] * (m + 2)
        for x in range(1, m + 1):
            prefix[x] = prefix[x - 1] + dp_prev[x]

        for x in range(1, m + 1):
            # previous elements y must satisfy:
            # y <= x/2 (since x >= 2*y, so y <= x/2)
            max_prev = x // 2
            if max_prev >= 1:
                dp_curr[x] = prefix[max_prev]
            else:
                dp_curr[x] = 0
        dp_prev = dp_curr

    return sum(dp_prev[1:])

