def get_total_number_of_sequences(m: int, n: int) -> int:
    # According to the clarification:
    # sequences are length n, values from 1 to m,
    # nondecreasing,
    # and each element is at least twice the previous one.
    #
    # For n=0, there's exactly one empty sequence, so return 1.
    if n == 0:
