def remove_column(collection, position):
    """
    Remove the element at zero-based index `position` from each inner grouping within a multi-level collection.
    The function returns a new collection with the same outer structure, where each inner grouping has the element
    at `position` removed if it exists.

    Parameters:
    - collection: a multi-level collection (e.g., list of lists, list of tuples)
    - position: zero-based index of the element to remove from each inner grouping

    Returns:
    - A new collection with the same type as `collection`, with each inner grouping having the element at `position` removed.
    """
    # Determine the type of outer collection to reconstruct the result accordingly
    outer_type = type(collection)
    # We assume inner groupings are sequences (list, tuple, etc.)
    result = []

    for inner in collection:
        # Convert inner to list for manipulation
        inner_list = list(inner)
        if 0 <= position < len(inner_list):
            del inner_list[position]
        # Convert back to original inner type if needed
        inner_type = type(inner)
        if inner_type is tuple:
            inner_result = tuple(inner_list)
        elif inner_type is list:
            inner_result = inner_list
        else:
            # For other sequence types, try to reconstruct
            try:
                inner_result = inner_type(inner_list)
            except Exception:
                # fallback to list if reconstruction fails
                inner_result = inner_list
        result.append(inner_result)

    # Reconstruct outer collection
    if outer_type is tuple:
        return tuple(result)
    elif outer_type is list:
        return result
    else:
        try:
            return outer_type(result)
        except Exception:
            return result

