def next_smallest_palindrome(num: int) -> int:
    s = str(num)
    length = len(s)

    # If all digits are 9, next palindrome is 10...01 with length+1 digits
    if all(ch == '9' for ch in s):
        return int('1' + ('0' * (length - 1)) + '1')

    def is_palindrome(x: str) -> bool:
        return x == x[::-1]

    def mirror_left_to_right(left: str, odd_length: bool) -> str:
        if odd_length:
            return left + left[:-1][::-1]
        else:
            return left + left[::-1]

    # Get left half (and middle if odd length)
    half_len = (length + 1) // 2
    left = s[:half_len]

    # Form palindrome by mirroring left part
    palindrome = mirror_left_to_right(left, length % 2 != 0)
    palindrome_num = int(palindrome)

    if palindrome_num > num:
        return palindrome_num

    # Increment the left half (including middle digit if odd length)
    left_num = int(left)
    left_num += 1
    left = str(left_num)

    # Handle if incrementing left changes its length (e.g. 999 -> 1000)
    if len(left) > half_len:
        # For this case, palindrome will be 1 followed by zeros and ending with 1
        return int('1' + ('0' * (length - 1)) + '1')

    palindrome = mirror_left_to_right(left, length % 2 != 0)
    return int(palindrome)

