def find_solution(a, b, n):
    if a == 0 and b == 0:
        return None if n != 0 else (0, 0)
    if a == 0:
        if n % b == 0:
            return (0, n // b)
        else:
            return None
    if b == 0:
        if n % a == 0:
            return (n // a, 0)
        else:
            return None

    for x in range(0, abs(n) + 1 if n >= 0 else 0, 1):
        remainder = n - a * x
        if b != 0 and remainder % b == 0:
            y = remainder // b
            return (x, y)
    return None

