def get_total_number_of_sequences(n: int, m: int) -> int:
    # dp[i][x]: number of sequences of length i ending with x
    # i from 1 to n, x from 1 to m
    dp = [ [0]*(m+1) for _ in range(n+1) ]

    # Base case: sequences of length 1 can start with any x in [1..m]
    for x in range(1, m+1):
        dp[1][x] = 1

    for i in range(2, n+1):
        for x in range(1, m+1):
            # previous element y must satisfy:
            # x >= 2*y  => y <= x//2
            # and y in [1..m]
            limit = x // 2
            if limit >= 1:
                # sum dp[i-1][y] for y in [1..limit]
                dp[i][x] = sum(dp[i-1][1:limit+1])
            else:
                dp[i][x] = 0

    return sum(dp[n][1:m+1])

