def filter_data(data, min_height=None, max_height=None, min_width=None, max_width=None):
    """
    Filters the input dictionary of students by height and width.

    Parameters:
    - data: dict of {student_name: {'height': numeric, 'width': numeric}}
            OR a dict with keys 'height' and 'width' whose values are lists of numbers
    - min_height: minimum height to include (inclusive), or None to ignore
    - max_height: maximum height to include (inclusive), or None to ignore
    - min_width: minimum width to include (inclusive), or None to ignore
    - max_width: maximum width to include (inclusive), or None to ignore

    Returns:
    - filtered dict with only students whose height and width are within the specified bounds
      OR, if input is {'height': [...], 'width': [...]}, returns a similarly structured dict filtered by index
    """

    # Detect input type: per-student dict or dict of lists
    if not isinstance(data, dict):
        raise TypeError("Input data must be a dictionary")
    if set(data.keys()) == {'height', 'width'} and isinstance(data['height'], list) and isinstance(data['width'], list):
        # Handle dict of lists case by filtering indices
        heights = data['height']
        widths = data['width']
        if len(heights) != len(widths):
            raise ValueError("Height and width lists must be of the same length")
        filtered_heights = []
        filtered_widths = []
        for h, w in zip(heights, widths):
            if h is None or w is None:
                continue
            if min_height is not None and h < min_height:
                continue
            if max_height is not None and h > max_height:
                continue
            if min_width is not None and w < min_width:
                continue
            if max_width is not None and w > max_width:
                continue
            filtered_heights.append(h)
            filtered_widths.append(w)
        return {'height': filtered_heights, 'width': filtered_widths}

    # Otherwise assume dict of {student_name: {'height': val, 'width': val}}
    filtered = {}
    for student, dims in data.items():
        if not isinstance(dims, dict):
            continue
        h = dims.get('height')
        w = dims.get('width')
        if h is None or w is None:
            continue
        if min_height is not None and h < min_height:
            continue
        if max_height is not None and h > max_height:
            continue
        if min_width is not None and w < min_width:
            continue
        if max_width is not None and w > max_width:
            continue
        filtered[student] = dims
    return filtered

