def is_triangleexists(*args):
    # Support either three separate angles or a single iterable of three angles
    if len(args) == 1:
        angles = args[0]
        if not hasattr(angles, '__iter__') or len(angles) != 3:
            return False
    elif len(args) == 3:
        angles = args
    else:
        return False

    a, b, c = angles
    return all(angle > 0 for angle in (a, b, c)) and abs(a + b + c - 180) < 1e-9

